<?php declare(strict_types=1); ?>
<?php if ($pageDefinition['filters'] !== []): ?><form class="frontend-filter-bar sigas-filter-panel" data-frontend-filter novalidate><div class="frontend-search-field sigas-filter-search"><i class="bi bi-search"></i><label class="visually-hidden" for="frontendSearch">Pesquisar</label><input class="form-control" id="frontendSearch" type="search" placeholder="<?= sigas_frontend_escape($pageDefinition['search_placeholder'] ?? 'Pesquisar registros') ?>" autocomplete="off" data-filter-search></div><?php foreach ($pageDefinition['filters'] as $index => $filter): ?><div><label class="visually-hidden" for="filter<?= $index ?>"><?= sigas_frontend_escape($filter['label']) ?></label><select class="form-select" id="filter<?= $index ?>" data-filter-select><option value=""><?= sigas_frontend_escape($filter['label']) ?>: todos</option><?php foreach ($filter['options'] as $option): ?><option value="<?= sigas_frontend_escape(strtolower($option)) ?>"><?= sigas_frontend_escape($option) ?></option><?php endforeach; ?></select></div><?php endforeach; ?><button class="btn btn-light sigas-filter-clear" type="reset"><i class="bi bi-arrow-counterclockwise"></i>Limpar</button></form><?php endif; ?>
